-- Stock transfers between branches (T-78). Tables generated by prisma migrate diff, then reviewed;
-- checks and triggers are hand-written.

-- AlterTable
ALTER TABLE "accounting"."posting_settings" ADD COLUMN     "transit_account_id" UUID;

-- AlterTable
ALTER TABLE "inventory"."stock_movement" ADD COLUMN     "transfer_id" UUID;

-- CreateTable
CREATE TABLE "inventory"."stock_transfer" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "number" TEXT NOT NULL,
    "from_branch_id" UUID NOT NULL,
    "to_branch_id" UUID NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'in_transit',
    "note" TEXT,
    "idempotency_key" TEXT NOT NULL,
    "dispatched_by" UUID NOT NULL,
    "dispatched_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "received_by" UUID,
    "received_at" TIMESTAMPTZ(6),
    "cancelled_by" UUID,
    "cancelled_at" TIMESTAMPTZ(6),
    "cancel_reason" TEXT,

    CONSTRAINT "stock_transfer_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "inventory"."stock_transfer_line" (
    "transfer_id" UUID NOT NULL,
    "line_no" INTEGER NOT NULL,
    "company_id" UUID NOT NULL,
    "part_id" UUID NOT NULL,
    "quantity" DECIMAL(14,3) NOT NULL,
    "value" DECIMAL(16,2) NOT NULL,
    "out_movement_id" UUID NOT NULL,
    "in_movement_id" UUID,
    "back_movement_id" UUID,

    CONSTRAINT "stock_transfer_line_pkey" PRIMARY KEY ("transfer_id","line_no")
);

-- CreateIndex
CREATE INDEX "stock_transfer_from_branch_id_status_idx" ON "inventory"."stock_transfer"("from_branch_id", "status");

-- CreateIndex
CREATE INDEX "stock_transfer_to_branch_id_status_idx" ON "inventory"."stock_transfer"("to_branch_id", "status");

-- CreateIndex
CREATE UNIQUE INDEX "stock_transfer_company_id_number_key" ON "inventory"."stock_transfer"("company_id", "number");

-- CreateIndex
CREATE UNIQUE INDEX "stock_transfer_company_id_idempotency_key_key" ON "inventory"."stock_transfer"("company_id", "idempotency_key");

-- CreateIndex
CREATE UNIQUE INDEX "stock_transfer_line_out_movement_id_key" ON "inventory"."stock_transfer_line"("out_movement_id");

-- CreateIndex
CREATE UNIQUE INDEX "stock_transfer_line_in_movement_id_key" ON "inventory"."stock_transfer_line"("in_movement_id");

-- CreateIndex
CREATE UNIQUE INDEX "stock_transfer_line_back_movement_id_key" ON "inventory"."stock_transfer_line"("back_movement_id");

-- AddForeignKey
ALTER TABLE "inventory"."stock_transfer" ADD CONSTRAINT "stock_transfer_company_id_from_branch_id_fkey" FOREIGN KEY ("company_id", "from_branch_id") REFERENCES "org"."branch"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock_transfer" ADD CONSTRAINT "stock_transfer_company_id_to_branch_id_fkey" FOREIGN KEY ("company_id", "to_branch_id") REFERENCES "org"."branch"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock_transfer_line" ADD CONSTRAINT "stock_transfer_line_transfer_id_fkey" FOREIGN KEY ("transfer_id") REFERENCES "inventory"."stock_transfer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock_transfer_line" ADD CONSTRAINT "stock_transfer_line_company_id_part_id_fkey" FOREIGN KEY ("company_id", "part_id") REFERENCES "inventory"."part"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- Hand-written rules -------------------------------------------------------

-- Movements: transfers out, in and back carry their transfer; nothing else does.
ALTER TABLE inventory.stock_movement DROP CONSTRAINT stock_movement_kind_valid;
ALTER TABLE inventory.stock_movement
  ADD CONSTRAINT stock_movement_kind_valid CHECK (kind IN (
    'receipt', 'adjustment_in', 'adjustment_out', 'issue', 'return', 'transfer_out', 'transfer_in', 'transfer_back')),
  ADD CONSTRAINT stock_movement_transfer CHECK ((kind LIKE 'transfer\_%') = (transfer_id IS NOT NULL));

ALTER TABLE inventory.stock_transfer
  ADD CONSTRAINT stock_transfer_branches CHECK (from_branch_id <> to_branch_id),
  ADD CONSTRAINT stock_transfer_status_valid CHECK (status IN ('in_transit', 'received', 'cancelled')),
  ADD CONSTRAINT stock_transfer_received_shape CHECK (
    (status = 'received') = (received_by IS NOT NULL) AND (received_by IS NULL) = (received_at IS NULL)),
  ADD CONSTRAINT stock_transfer_cancelled_shape CHECK (
    (status = 'cancelled') = (cancelled_by IS NOT NULL)
    AND (cancelled_by IS NULL) = (cancelled_at IS NULL)
    AND (cancelled_by IS NULL) = (cancel_reason IS NULL));

ALTER TABLE inventory.stock_transfer_line
  ADD CONSTRAINT stock_transfer_line_values CHECK (quantity > 0 AND value > 0),
  ADD CONSTRAINT stock_transfer_line_end CHECK (in_movement_id IS NULL OR back_movement_id IS NULL);

-- A transfer only moves forward once (in transit → received or cancelled); never deleted.
CREATE OR REPLACE FUNCTION inventory.guard_stock_transfer() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.status <> 'in_transit' OR NEW.status NOT IN ('received', 'cancelled')
     OR (to_jsonb(NEW) - ARRAY['status', 'received_by', 'received_at', 'cancelled_by', 'cancelled_at', 'cancel_reason'])
        IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['status', 'received_by', 'received_at', 'cancelled_by', 'cancelled_at', 'cancel_reason']) THEN
    RAISE EXCEPTION 'stock_transfer_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER stock_transfer_guard BEFORE UPDATE OR DELETE ON inventory.stock_transfer
  FOR EACH ROW EXECUTE FUNCTION inventory.guard_stock_transfer();

-- A line's part, quantity, value and dispatch never change; its arrival or return is set once.
CREATE OR REPLACE FUNCTION inventory.guard_stock_transfer_line() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE'
     OR (to_jsonb(NEW) - ARRAY['in_movement_id', 'back_movement_id'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['in_movement_id', 'back_movement_id'])
     OR (OLD.in_movement_id IS NOT NULL AND NEW.in_movement_id IS DISTINCT FROM OLD.in_movement_id)
     OR (OLD.back_movement_id IS NOT NULL AND NEW.back_movement_id IS DISTINCT FROM OLD.back_movement_id) THEN
    RAISE EXCEPTION 'stock_transfer_line_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER stock_transfer_line_guard BEFORE UPDATE OR DELETE ON inventory.stock_transfer_line
  FOR EACH ROW EXECUTE FUNCTION inventory.guard_stock_transfer_line();

-- At commit: a transfer has lines; received means every line arrived, cancelled every line went
-- back, in transit none did.
CREATE OR REPLACE FUNCTION inventory.check_stock_transfer() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  t inventory.stock_transfer%ROWTYPE;
BEGIN
  SELECT * INTO t FROM inventory.stock_transfer WHERE id = NEW.id;
  IF NOT EXISTS (SELECT 1 FROM inventory.stock_transfer_line l WHERE l.transfer_id = t.id)
     OR EXISTS (
       SELECT 1 FROM inventory.stock_transfer_line l
        WHERE l.transfer_id = t.id
          AND NOT CASE t.status
                    WHEN 'in_transit' THEN l.in_movement_id IS NULL AND l.back_movement_id IS NULL
                    WHEN 'received' THEN l.in_movement_id IS NOT NULL
                    ELSE l.back_movement_id IS NOT NULL
                  END) THEN
    RAISE EXCEPTION 'stock_transfer_lines_mismatch' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER stock_transfer_consistent AFTER INSERT OR UPDATE ON inventory.stock_transfer
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION inventory.check_stock_transfer();
